func rowID(id int) string { return fmt.Sprintf("todo-row-%d", id) }

// priorityVariant maps a priority string to a badge variant.
func priorityVariant(p string) badge.Variant {
	switch p {
	case "high":
		return badge.Danger
	case "low":
		return badge.Secondary
	default:
		return badge.Warning
	}
}

